217	  car.add(carBack);
218	
219	  // Transparent side walls.
220	  const leftSide = new THREE.Mesh(new THREE.BoxGeometry(0.08, FLOOR_HEIGHT - 0.3, SHAFT_DEPTH - 0.3), sideMaterial);
221	  leftSide.position.set(-halfShaftX + 0.12, FLOOR_HEIGHT / 2, 0);
222	  leftSide.renderOrder = 2;
223	  car.add(leftSide);
224	
225	  const rightSide = new THREE.Mesh(new THREE.BoxGeometry(0.08, FLOOR_HEIGHT - 0.3, SHAFT_DEPTH - 0.3), sideMaterial);
226	  rightSide.position.set(halfShaftX - 0.12, FLOOR_HEIGHT / 2, 0);
227	  rightSide.renderOrder = 2;
228	  car.add(rightSide);
229	
230	  // Two sliding front doors. Closed: they meet at x = 0. Open: they retract
231	  // outward toward their own side.
232	  const leftDoor = new THREE.Mesh(new THREE.BoxGeometry(doorWidth, doorHeight, 0.1), doorMaterial);
233	  leftDoor.position.set(-doorWidth / 2, doorHeight / 2 + 0.12, halfShaftZ - 0.05);
234	  leftDoor.renderOrder = 3;
235	  car.add(leftDoor);
236	
237	  const rightDoor = new THREE.Mesh(new THREE.BoxGeometry(doorWidth, doorHeight, 0.1), doorMaterial);
238	  rightDoor.position.set(doorWidth / 2, doorHeight / 2 + 0.12, halfShaftZ - 0.05);
239	  rightDoor.renderOrder = 3;
240	  car.add(rightDoor);
241	
242	  car.leftDoor = leftDoor;
243	  car.rightDoor = rightDoor;
244	  car.userData.doorWidth = doorWidth;
245	
246	  return car;
247	}
248	
249	// ---------------------------------------------------------------------------
250	// Sequential action pipeline
251	// ---------------------------------------------------------------------------
252	
253	function queueActions(actions) {
254	  for (let i = 0; i < actions.length; i++) {
255	    actionQueue.push(actions[i]);
256	  }
257	}
258	
259	function beginAction(action) {
260	  currentAction = action;
261	  if (action.type === "move") {
262	    action.startPos = action.person.position.clone();
263	    action.direction = new THREE.Vector3().subVectors(action.target, action.startPos);
264	    action.distance = action.direction.length();
265	    action.person.userData.isWalking = action.distance > 0.0001;
266	    if (action.distance > 0.0001) {
267	      action.direction.normalize();
268	    }
269	    action.traveled = 0;
270	  } else if (action.type === "rotateTo") {
271	    action.startQuat = action.person.quaternion.clone();
272	    action.person.lookAt(action.target.x, action.person.position.y, action.target.z);
273	    action.endQuat = action.person.quaternion.clone();
274	    action.person.quaternion.copy(action.startQuat);
275	    action.t = 0;
276	    action.duration = action.duration || 0.3;
277	  } else if (action.type === "doors") {
278	    doorsAnimating = { target: action.target };
279	  } else if (action.type === "delay" || action.type === "function") {
280	    action.t = 0;
281	  }
282	}
283	
284	function advanceAction(deltaTime) {
285	  const action = currentAction;
286	  if (action.type === "move") {
287	    action.traveled += PERSON_MOVE_SPEED * speedSlider.value * deltaTime;
288	    if (action.traveled >= action.distance - 0.01) {
289	      action.person.position.copy(action.target);
290	      action.person.userData.isWalking = false;
291	      return true;
292	    }
293	    action.person.position.copy(action.startPos).addScaledVector(action.direction, action.traveled);
294	    return false;
295	  }
296	  if (action.type === "rotateTo") {
297	    action.t += deltaTime;
298	    const t = Math.min(action.t / action.duration, 1);
299	    action.person.quaternion.slerpQuaternions(action.startQuat, action.endQuat, t);
300	    return t >= 1 - 0.0001;
301	  }
302	  if (action.type === "delay") {
303	    action.t += deltaTime;
304	    return action.t >= action.seconds;
305	  }
306	  if (action.type === "reparent") {
307	    action.targetParent.attach(action.person);
308	    return true;
309	  }
310	  if (action.type === "doors") {
311	    advanceDoors(deltaTime);
312	    return doorsAnimating === null;
313	  }
314	  if (action.type === "function") {
315	    action.fn();
316	    return true;
317	  }
318	  return true;
319	}
320	
321	function updateActions(deltaTime) {
322	  if (!currentAction && actionQueue.length > 0) {
323	    beginAction(actionQueue.shift());
324	  }
325	  if (currentAction && advanceAction(deltaTime)) {
326	    currentAction = null;
327	  }
328	}
329	
330	function queueWalkWorld(person, worldTarget) {
331	  queueActions([
332	    { type: "rotateTo", person: person, target: worldTarget.clone() },
333	    { type: "move", person: person, target: worldTarget.clone() }
334	  ]);
335	}
336	
337	function queueWalkCarLocal(person, worldTarget) {
338	  elevatorCar.updateWorldMatrix(true, false);
339	  const localTarget = worldTarget.clone().applyMatrix4(new THREE.Matrix4().copy(elevatorCar.matrixWorld).invert());
340	  queueActions([
341	    { type: "rotateTo", person: person, target: localTarget.clone() },
342	    { type: "move", person: person, target: localTarget }
343	  ]);
344	}
345	
346	// ---------------------------------------------------------------------------
347	// Doors and elevator travel
348	// ---------------------------------------------------------------------------
349	
350	function advanceDoors(deltaTime) {
351	  if (!doorsAnimating) {
352	    return;
353	  }
354	  const target = doorsAnimating.target;
355	  const step = (2 / 3) * speedSlider.value * deltaTime;
356	  if (doorState < target) {
357	    doorState = Math.min(doorState + step, target);
358	  } else {
359	    doorState = Math.max(doorState - step, target);
360	  }
361	  const doorWidth = elevatorCar.userData.doorWidth;
362	  elevatorCar.leftDoor.position.x = -doorWidth / 2 - doorState * (doorWidth - 0.1);
363	  elevatorCar.rightDoor.position.x = doorWidth / 2 + doorState * (doorWidth - 0.1);
364	  if (Math.abs(doorState - target) < 0.01) {
365	    doorState = target;
366	    doorsAnimating = null;
367	  }
368	}
369	
370	function updateElevator(deltaTime) {
371	  if (Math.abs(elevatorY - elevatorTargetY) < 0.01) {
372	    elevatorY = elevatorTargetY;
373	    if (elevatorOnArrive) {
374	      const callback = elevatorOnArrive;
375	      elevatorOnArrive = null;
376	      callback();
377	    }
378	    return;
379	  }
380	  const step = ELEVATOR_SPEED * speedSlider.value * deltaTime;
381	  if (elevatorY < elevatorTargetY) {
382	    elevatorY = Math.min(elevatorY + step, elevatorTargetY);
383	  } else {
384	    elevatorY = Math.max(elevatorY - step, elevatorTargetY);
385	  }
386	}
387	
388	function moveElevatorTo(floorIndex, onArrive) {
389	  elevatorTargetY = floorY(floorIndex);
390	  elevatorOnArrive = onArrive;
391	}
392	
393	function updateHud(text) {
394	  if (hudStatus) {
395	    hudStatus.textContent = text;
396	  }
397	}
398	
399	function updatePeople() {
400	  for (let i = 0; i < people.length; i++) {
401	    const person = people[i];
402	    if (!person) {
403	      continue;
404	    }
405	    if (person.userData.isWalking) {
406	      const swing = Math.sin(elapsed * 9) * 0.6;
407	      person.userData.leftLeg.rotation.x = swing;
408	      person.userData.rightLeg.rotation.x = -swing;
409	    } else {
410	      person.userData.leftLeg.rotation.x = 0;
411	      person.userData.rightLeg.rotation.x = 0;
412	    }
413	  }
414	}
415	
416	// ---------------------------------------------------------------------------
417	// Simulation logic: one floor is always empty; every other floor has a person.
418	// Each round, the closest occupied floor's person rides to the empty floor.
419	// ---------------------------------------------------------------------------
420	
421	function pickPickupFloor() {
422	  let bestFloor = -1;
423	  let bestDistance = Infinity;
424	  const carFloor = Math.round(elevatorY / FLOOR_HEIGHT);
425	  for (let f = 0; f < FLOOR_COUNT; f++) {
426	    if (f === emptyFloor) {
427	      continue;
428	    }
429	    const distance = Math.abs(f - carFloor);
430	    if (distance < bestDistance) {
431	      bestDistance = distance;
432	      bestFloor = f;
433	    }
434	  }
435	  return bestFloor;
436	}
437	
438	function queueRound() {
439	  roundIndex++;
440	  const pickupFloor = pickPickupFloor();
441	  const rider = people[pickupFloor];
442	  const destFloor = emptyFloor;
443	  updateHud("Round " + roundIndex + ": picking up on floor " + pickupFloor);
444	
445	  moveElevatorTo(pickupFloor, function () {
446	    updateHud("Round " + roundIndex + ": boarding on floor " + pickupFloor);
447	    queueActions([
448	      { type: "doors", target: 1 },
449	      { type: "delay", seconds: 0.3 }
450	    ]);
451	    queueWalkWorld(rider, new THREE.Vector3(0, floorY(pickupFloor), BUILDING_DEPTH / 2 + 0.6));
452	    queueActions([
453	      { type: "reparent", person: rider, targetParent: elevatorCar }
454	    ]);
455	    queueWalkCarLocal(rider, new THREE.Vector3(0, 0, -0.8));
456	    queueActions([
457	      { type: "delay", seconds: 0.3 },
458	      { type: "doors", target: 0 },
459	      { type: "delay", seconds: 0.3 },
460	      { type: "function", fn: function () {
461	        updateHud("Round " + roundIndex + ": riding to floor " + destFloor);
462	        moveElevatorTo(destFloor, function () {
463	          queueActions([
464	            { type: "doors", target: 1 },
465	            { type: "delay", seconds: 0.3 },
466	            { type: "reparent", person: rider, targetParent: scene }
467	          ]);
468	          queueWalkWorld(rider, new THREE.Vector3(0, floorY(destFloor), WAIT_Z));
469	          queueActions([
470	            { type: "delay", seconds: 0.3 },
471	            { type: "doors", target: 0 },
472	            { type: "function", fn: function () {
473	              emptyFloor = pickupFloor;
474	              updateHud("Round " + roundIndex + " complete: floor " + destFloor + " occupied");
475	              queueRound();
476	            } }
477	          ]);
478	        });
479	      } }
480	    ]);
481	  });
482	}
483	
484	// ---------------------------------------------------------------------------
485	// Startup
486	// ---------------------------------------------------------------------------
487	
488	function createPeople() {
489	  for (let f = 0; f < FLOOR_COUNT; f++) {
490	    if (f === emptyFloor) {
491	      people[f] = null;
492	      continue;
493	    }
494	    const person = createPerson();
495	    person.position.set(1.6 + f * 0.7, floorY(f), WAIT_Z);
496	    person.lookAt(0, floorY(f), 0);
497	    setGroupRenderOrder(person, 5);
498	    scene.add(person);
499	    people[f] = person;
500	  }
501	}
502	
503	function startSimulation() {
504	  scene = new THREE.Scene();
505	  scene.background = new THREE.Color(0x20242a);
506	
507	  camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);
508	  camera.position.set(25, 25, 25);
509	  camera.lookAt(0, (FLOOR_COUNT * FLOOR_HEIGHT) / 2, 0);
510	
511	  renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
512	  renderer.setSize(window.innerWidth, window.innerHeight);
513	  renderer.sortObjects = true;
514	  document.body.appendChild(renderer.domElement);
515	
516	  controls = new THREE.OrbitControls(camera, renderer.domElement);
517	  controls.target.set(0, (FLOOR_COUNT * FLOOR_HEIGHT) / 2, 0);
518	  controls.enableDamping = true;
519	  controls.update();
520	
521	  scene.add(new THREE.AmbientLight(0xffffff, 0.55));
522	  const sun = new THREE.DirectionalLight(0xffffff, 0.8);
523	  sun.position.set(20, 30, 10);
524	  scene.add(sun);
525	
526	  createBuilding();
527	
528	  elevatorCar = createElevatorCar();
529	  elevatorCar.position.y = floorY(0);
530	  scene.add(elevatorCar);
531	
532	  clock = new THREE.Clock();
533	  speedSlider = document.getElementById("speed-slider");
534	  const speedValue = document.getElementById("speed-value");
535	  if (speedSlider && speedValue) {
536	    speedSlider.addEventListener("input", function () {
537	      speedValue.textContent = speedSlider.value + "x";
538	    });
539	  }
540	
541	  const hud = document.createElement("div");
542	  hud.style.cssText = "position:fixed;top:12px;right:12px;z-index:10;padding:8px 12px;" +
543	    "background:rgba(15,18,24,0.75);color:#e8ecf2;border:1px solid rgba(255,255,255,0.25);" +
544	    "border-radius:8px;font-family:Arial,Helvetica,sans-serif;font-size:13px;";
545	  document.body.appendChild(hud);
546	  hudStatus = hud;
547	
548	  window.addEventListener("resize", function () {
549	    camera.aspect = window.innerWidth / window.innerHeight;
550	    camera.updateProjectionMatrix();
551	    renderer.setSize(window.innerWidth, window.innerHeight);
552	  });
553	
554	  createPeople();
555	  queueRound();
556	  animate();
557	}
558	
559	function animate() {
560	  requestAnimationFrame(animate);
561	  const deltaTime = clock.getDelta();
562	  elapsed += deltaTime * speedSlider.value;
563	  updateElevator(deltaTime);
564	  updateActions(deltaTime);
565	  updatePeople();
566	  elevatorCar.position.y = elevatorY;
567	  controls.update();
568	  renderer.render(scene, camera);
569	}
570	
571	if (document.readyState === "loading") {
572	  window.addEventListener("DOMContentLoaded", startSimulation);
573	} else {
574	  startSimulation();
575	}
